# RWDM_TWIST: Twist: rotate portions around an axis. The script rwdm_twist_script.txt is generated by rwdm_gen.py (the closed forms are in that file); every case moves each Point object
# from its closed-form image E_k to the origin and lists it: the app prints a coordinate within 1e-9 of an integer as that integer, so a
# passing case means every image lies within 1e-9 of the textbook formula (a residual of 1e-6 would read 1e-06; RWDM_*_sensitivity checks that).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_TWIST_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_twist_script.txt" 2>&1)" || { echo "$RWDM_TWIST_OUT" | tail -40; echo "FAIL RWDM_TWIST_run: script exited non-zero"; fail=1; RWDM_TWIST_OUT=""; }
else
  RWDM_TWIST_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_twist_script.txt" 2>&1)" || { echo "$RWDM_TWIST_OUT" | tail -40; echo "FAIL RWDM_TWIST_run: script exited non-zero"; fail=1; RWDM_TWIST_OUT=""; }
fi
rwdm_twist_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_TWIST_OUT"; }
# rwdm_twist_check NAME N DESC: the case listed exactly N points and every one of them is "0,0,0" (the residual to the closed form)
rwdm_twist_check() {
  local blk npts zeros; blk="$(rwdm_twist_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ]; then echo "ok   RWDM_TWIST_$1: $3 ($2 points, every one within 1e-9 of the closed form)"
  else echo "FAIL RWDM_TWIST_$1: $3 (listed $npts points, $zeros at residual 0; expected $2 and $2)"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -12 | sed 's/^/     residual: /'; fi
}
rwdm_twist_check z90 5 "Twist 90 degrees over the axis (0,0,0)->(0,0,4): each point turns about the axis by 90 degrees times its clamped axial fraction"
rwdm_twist_check oblique 5 "Twist -60 degrees over the oblique axis (1,0,0)->(1,3,4) (length 5)"
# negative control: the same harness must SEE a 1e-6 error (point moved 1e-6 off its expected image reads 1e-06, not 0)
rwdm_twist_sens() {
  local blk; blk="$(rwdm_twist_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RWDM_TWIST_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RWDM_TWIST_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rwdm_twist_sens
